-- =============================================================================
-- V2__catalogo_problemas.sql
-- Catálogo de problemas odontológicos usado na triagem do consultório (WhatsApp).
--
-- Fontes:
--  * CID-10 em português: DATASUS/Ministério da Saúde, CID-10 versão 2008
--    (http://www2.datasus.gov.br/cid10/V2008/cid10.htm), arquivo oficial de
--    subcategorias CID-10-SUBCATEGORIAS.CSV (pacote CID10CSV do DATASUS).
--    Capítulo XI, bloco K00-K14 (doenças da cavidade oral, glândulas salivares e
--    maxilares), além de B00.1, B37.0 (cap. I), F45.8 (cap. V), Q38.1 (cap. XVII),
--    R19.6, R68.2 (cap. XVIII), S01.5, S02.5, S02.6, S03.0, S03.2, T81.0, T81.8,
--    T85.6, T85.7 (cap. XIX) e Z01.2, Z29.8, Z41.8, Z46.3, Z46.4 (cap. XXI).
--  * Termos de inclusão conferidos na CID-10 da OMS, versão 2019
--    (https://icd.who.int/browse10/2019/en), ex.: K08.8 inclui "dor de dente SOE",
--    K03.8 inclui "dentina sensível", K05.2 inclui "pericoronarite aguda" e
--    "abscesso periodontal", K12.2 inclui "abscesso submandibular", F45.8 inclui
--    "ranger de dentes", K12.1 inclui "estomatite por prótese", Z01.2 = exame dentário.
--    Códigos usados somente se existentes na tabela do DATASUS (ex.: K02.5 e K12.3,
--    criados pela OMS após 2008, NÃO foram usados).
--  * Especialidades: nomes das especialidades odontológicas reconhecidas pelo
--    Conselho Federal de Odontologia (Consolidação das Normas, Resolução CFO-63/2005
--    e alterações posteriores - https://website.cfo.org.br/). "Clínica Geral" não é
--    especialidade e é usada para itens de rotina/clínico geral.
--  * Prioridade: EMERGENCIA = inchaço no rosto/pescoço com febre ou dificuldade para
--    engolir/respirar, sangramento que não para, dente arrancado ou trauma recente;
--    URGENCIA = dor intensa, pulpite, abscesso sem sinais sistêmicos, fratura com dor,
--    alveolite, pericoronarite, lesão que não cicatriza; ROTINA = demais.
--  * palavras_chave: separadas por ";", em minúsculas, sem repetição entre itens.
-- O código CID-10 é apenas referência para triagem; o diagnóstico é do cirurgião-dentista.
-- =============================================================================

INSERT INTO problema_odontologico (codigo, nome, descricao, especialidade, prioridade, cid10, palavras_chave) VALUES
    -- CELULITE_ABSCESSO_DISSEMINADO: K12.2 inclui celulite do assoalho da boca e abscesso submandibular; celulite da face isolada = L03.2
    ('CELULITE_ABSCESSO_DISSEMINADO', 'Inchaço no rosto ou pescoço com febre (infecção disseminada)', 'Inchaço que se espalha pelo rosto, olho ou pescoço, com febre, dificuldade para engolir, respirar ou abrir a boca; procure atendimento imediato.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'EMERGENCIA', 'K12.2', 'rosto inchado;cara inchada;inchaço no pescoço;pescoço inchado;inchaço com febre;dificuldade para engolir;dificuldade para respirar;falta de ar com inchaço;não consigo abrir a boca;olho inchado por causa do dente;inchaço embaixo do queixo;bochecha muito inchada'),
    ('SANGRAMENTO_POS_EXTRACAO', 'Sangramento que não para após extração', 'Sangramento na boca que não para mesmo após compressão com gaze por 30 minutos, depois de extração ou cirurgia; precisa de atendimento imediato.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'EMERGENCIA', 'T81.0', 'sangramento que não para;sangue não para;não para de sangrar;sangrando depois de arrancar;sangrando depois da extração;boca sangrando muito;hemorragia na boca;sangrando sem parar;muito sangue na boca'),
    -- AVULSAO_DENTARIA: na CID-10 a avulsão é classificada como luxação (deslocamento) dentária, S03.2
    ('AVULSAO_DENTARIA', 'Dente arrancado por trauma (avulsão)', 'Dente que saiu inteiro da boca após queda ou pancada; guarde-o no leite ou na saliva, sem esfregar, e procure atendimento imediatamente.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'EMERGENCIA', 'S03.2', 'dente arrancado;dente saiu inteiro;dente saiu da boca;avulsão;caí e perdi o dente;dente caiu na queda;dente caiu com a pancada;dente arrancou na briga;guardei o dente no leite'),
    ('LUXACAO_DENTARIA', 'Dente deslocado após pancada (luxação)', 'Dente que mudou de posição, afundou, ficou torto ou mole logo após uma pancada; trauma recente precisa de atendimento imediato.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'EMERGENCIA', 'S03.2', 'dente entortou na pancada;dente afundou;dente empurrado;dente deslocado;dente saiu do lugar;dente mole depois da queda;dente entrou na gengiva;dente torto depois da pancada'),
    ('TRAUMA_BUCAL_RECENTE', 'Trauma recente na boca (queda, pancada, corte)', 'Pancada, queda ou acidente recente atingindo boca, lábios ou dentes, com corte, sangramento ou dor; precisa de avaliação imediata.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'EMERGENCIA', 'S01.5', 'bati a boca;pancada na boca;caí de boca;levei soco na boca;cortei o lábio;corte na boca;lábio cortado;boca machucada na queda;acidente de bicicleta;bolada na boca;criança caiu e bateu o dente'),
    ('FRATURA_MANDIBULA', 'Fratura de mandíbula ou maxilar', 'Suspeita de osso do rosto ou da mandíbula quebrado após trauma, com dor forte, inchaço ou dentes que não encaixam mais; procure pronto-socorro.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'EMERGENCIA', 'S02.6', 'fratura na mandíbula;mandíbula quebrada;quebrei o maxilar;maxilar quebrado;queixo quebrado;fratura no rosto;osso da face quebrado;dentes não encaixam depois da pancada'),
    -- DOR_DE_DENTE: K08.8 inclui "dor de dente SOE" (Toothache NOS)
    ('DOR_DE_DENTE', 'Dor de dente', 'Dor em um ou mais dentes ainda sem causa definida; o dentista vai examinar para descobrir a origem.', 'Clínica Geral', 'URGENCIA', 'K08.8', 'dor de dente;dente doendo;dor no dente;dente latejando;dor forte no dente;dente dói;dor de dente a noite;remédio não passa a dor;não durmo de dor de dente;dor insuportável no dente'),
    ('PULPITE', 'Pulpite (inflamação do nervo do dente)', 'Inflamação da polpa (nervo) do dente, com dor espontânea, latejante ou que demora a passar após frio ou calor.', 'Endodontia', 'URGENCIA', 'K04.0', 'pulpite;nervo do dente;nervo inflamado;dor ao tomar gelado;dor com bebida quente;dor que demora a passar;dor que irradia pro ouvido;dor latejante;dente pulsando;dor que vem do nada'),
    ('NECROSE_PULPAR', 'Necrose pulpar (dente "morto")', 'Morte do nervo do dente, muitas vezes sem dor, com o dente escurecendo; precisa de tratamento de canal para evitar abscesso.', 'Endodontia', 'ROTINA', 'K04.1', 'dente morto;nervo morto;dente escurecido;dente cinza;dente ficou escuro depois da pancada;necrose;necrose pulpar;dente sem vida'),
    -- TRATAMENTO_CANAL: K04.9: outras doenças da polpa e dos tecidos periapicais e as não especificadas
    ('TRATAMENTO_CANAL', 'Tratamento de canal (endodontia)', 'Indicação de tratamento ou retratamento de canal, ou canal já iniciado que precisa ser continuado.', 'Endodontia', 'ROTINA', 'K04.9', 'tratamento de canal;fazer canal;terminar o canal;canal começado;retratamento de canal;refazer o canal;precisa de canal;curativo de canal;endodontia;endodontista'),
    ('PERIODONTITE_APICAL_AGUDA', 'Dor ao morder (periodontite apical aguda)', 'Dor forte ao morder ou ao tocar o dente, com sensação de dente "alto", geralmente por inflamação na ponta da raiz.', 'Endodontia', 'URGENCIA', 'K04.4', 'dor ao morder;dor ao mastigar;dente parece alto;dente crescido;dor depois do canal;dente dolorido ao tocar;não consigo morder;dói quando encosto o dente'),
    ('ABSCESSO_COM_FISTULA', 'Abscesso dentário com fístula', 'Infecção na ponta da raiz que drena pus por uma "bolinha" na gengiva (fístula); geralmente com pouca dor.', 'Endodontia', 'URGENCIA', 'K04.6', 'fístula;bolinha de pus na gengiva;espinha na gengiva;pus saindo da gengiva;bolinha na gengiva que sai pus;gosto de pus;caroço na gengiva com pus;bolinha que enche e esvazia'),
    ('ABSCESSO_SEM_FISTULA', 'Abscesso dentário sem fístula', 'Infecção com pus na ponta da raiz, com dor e inchaço localizado na gengiva, sem febre nem inchaço que se espalha pelo rosto.', 'Endodontia', 'URGENCIA', 'K04.7', 'abscesso;abcesso;dente inflamado;inchaço no dente;dente com pus;inchaço na gengiva perto do dente;dente infeccionado;infecção no dente;gengiva inchada e doendo'),
    ('CARIE', 'Cárie dentária', 'Destruição do dente causada por bactérias, com buracos, manchas escuras ou comida prendendo no dente.', 'Dentística', 'ROTINA', 'K02.1', 'carie;cárie;buraco no dente;dente furado;dente preto;mancha preta no dente;dente podre;dente cariado;comida entrando no dente;dente esfarelando'),
    -- RESTAURACAO_QUEBRADA: sem código específico para restauração insatisfatória na CID-10 OMS/DATASUS (K08.5 existe só na CID-10-CM); usado K08.8
    ('RESTAURACAO_QUEBRADA', 'Restauração (obturação) quebrada ou caída', 'Restauração ou "obturação" que caiu, quebrou ou ficou com falha, deixando o dente aberto.', 'Dentística', 'ROTINA', 'K08.8', 'restauração caiu;obturação caiu;caiu a massinha;restauração quebrou;obturação quebrada;caiu o chumbo;resina caiu;resina quebrou;perdi a obturação;buraco onde tinha restauração'),
    ('FRATURA_DENTAL', 'Dente quebrado ou trincado (fratura dental)', 'Dente lascado, partido ou trincado ao morder ou por pancada antiga; se houver dor, precisa de atendimento breve.', 'Dentística', 'URGENCIA', 'S02.5', 'dente quebrado;dente lascado;quebrei o dente;pedaço do dente caiu;dente partido;dente rachado;dente trincado;lasquei o dente;dente quebrou ao morder;dente partiu ao meio'),
    -- HIPERSENSIBILIDADE_DENTINARIA: K03.8 inclui "dentina sensível" (Sensitive dentine)
    ('HIPERSENSIBILIDADE_DENTINARIA', 'Sensibilidade nos dentes (hipersensibilidade dentinária)', 'Dor rápida, tipo choque, ao contato com frio, doce, ar ou escovação, que passa logo após o estímulo.', 'Dentística', 'ROTINA', 'K03.8', 'sensibilidade;dente sensível;sensibilidade ao gelado;dente sensível ao frio;choque no dente;dor com água gelada;sensibilidade nos dentes;arrepio no dente;dói ao escovar;pasta para sensibilidade'),
    ('EROSAO_DENTAL', 'Erosão dental (desgaste por ácido)', 'Perda do esmalte por ácidos da alimentação, refrigerantes, refluxo ou vômitos frequentes.', 'Dentística', 'ROTINA', 'K03.2', 'erosão;erosão dental;esmalte gasto por ácido;dente transparente;dente afinando;refluxo estragando os dentes;dente corroído;refrigerante corroendo o dente'),
    ('ABRASAO_DENTAL', 'Abrasão dental (desgaste perto da gengiva)', 'Desgaste do dente, geralmente perto da gengiva, causado por escovação muito forte ou hábitos como morder objetos.', 'Dentística', 'ROTINA', 'K03.1', 'abrasão;escovação forte;dente lixado;desgaste perto da gengiva;lesão cervical;degrau no dente;dente cavado no colo;escova dura gastou o dente'),
    ('DESGASTE_DENTAL', 'Desgaste dos dentes (atrito)', 'Dentes gastos ou mais curtos pelo contato excessivo entre eles, muitas vezes ligado ao ranger ou apertar dos dentes.', 'Dentística', 'ROTINA', 'K03.0', 'dente gasto;dentes gastos;desgaste dental;desgaste nos dentes;dente ficando curto;dentes diminuindo;atrito dental;pontas dos dentes gastas'),
    ('MANCHAS_DENTES', 'Manchas e alteração de cor nos dentes', 'Dentes amarelados, escurecidos ou manchados por café, cigarro, medicamentos ou outras causas.', 'Dentística', 'ROTINA', 'K03.7', 'dente manchado;mancha no dente;dente escuro;dente amarelado;dentes amarelos;mancha de café;mancha de cigarro;dente encardido;dente sem cor'),
    ('FLUOROSE', 'Fluorose dentária', 'Manchas brancas ou marrons no esmalte causadas por excesso de flúor durante a formação dos dentes.', 'Dentística', 'ROTINA', 'K00.3', 'fluorose;manchas brancas no dente;dente com manchas brancas;dente pintado;mancha esbranquiçada;manchas marrons no esmalte;dente mosqueado'),
    -- CLAREAMENTO: procedimento estético sem doença: Z41.8 (outros procedimentos para outros propósitos exceto cuidados de saúde)
    ('CLAREAMENTO', 'Clareamento dental', 'Procedimento estético para deixar os dentes mais brancos, feito no consultório ou em casa com moldeira.', 'Dentística', 'ROTINA', 'Z41.8', 'clareamento;clarear os dentes;dentes mais brancos;branquear os dentes;clareamento a laser;clareamento caseiro;moldeira de clareamento;deixar os dentes brancos'),
    -- ESTETICA_SORRISO: procedimento estético: Z41.8
    ('ESTETICA_SORRISO', 'Estética do sorriso (facetas, lentes, resinas)', 'Interesse em melhorar a aparência do sorriso com facetas, lentes de contato dental ou restaurações estéticas.', 'Dentística', 'ROTINA', 'Z41.8', 'lente de contato dental;lentes de contato nos dentes;facetas;faceta de resina;faceta de porcelana;estética do sorriso;design do sorriso;sorriso gengival;melhorar o sorriso;fechar espaço com resina'),
    ('GENGIVITE', 'Gengivite', 'Inflamação da gengiva, que fica vermelha, inchada e sensível, geralmente por acúmulo de placa bacteriana.', 'Periodontia', 'ROTINA', 'K05.1', 'gengivite;gengiva inflamada;gengiva vermelha;gengiva inchada;gengiva dolorida;gengiva sensível;inflamação na gengiva'),
    -- SANGRAMENTO_GENGIVAL: sangramento gengival é sinal de gengivite: K05.1 (gengivite crônica)
    ('SANGRAMENTO_GENGIVAL', 'Sangramento na gengiva', 'Gengiva que sangra ao escovar, passar fio dental ou espontaneamente, sinal comum de gengivite ou periodontite.', 'Periodontia', 'ROTINA', 'K05.1', 'gengiva sangrando;sangra ao escovar;sangue na escova;sangramento na gengiva;gengiva sangra;sangue ao passar fio dental;cuspo sangue ao escovar;acordo com sangue na boca'),
    ('PERIODONTITE', 'Periodontite (doença da gengiva e do osso)', 'Doença que destrói a gengiva e o osso que sustentam os dentes, podendo causar mau hálito, dentes moles e perda dentária.', 'Periodontia', 'ROTINA', 'K05.3', 'periodontite;piorreia;doença periodontal;gengiva descolando do dente;bolsa periodontal;perda óssea;osso do dente;tratamento de gengiva;periodontista'),
    -- ABSCESSO_PERIODONTAL: K05.2 (periodontite aguda) inclui abscesso periodontal
    ('ABSCESSO_PERIODONTAL', 'Abscesso na gengiva (abscesso periodontal)', 'Acúmulo de pus na gengiva ao lado do dente, com inchaço e dor, geralmente ligado à doença periodontal.', 'Periodontia', 'URGENCIA', 'K05.2', 'abscesso na gengiva;abscesso periodontal;gengiva com pus;gengiva estufada;pus entre o dente e a gengiva;gengiva inchada com pus'),
    ('RETRACAO_GENGIVAL', 'Retração gengival', 'Gengiva que "desce" e deixa a raiz do dente exposta, deixando o dente mais comprido e sensível.', 'Periodontia', 'ROTINA', 'K06.0', 'retração gengival;gengiva retraída;gengiva baixando;gengiva recuando;raiz aparecendo;dente parecendo maior;gengiva descendo;raiz exposta'),
    -- MOBILIDADE_DENTARIA: sem código específico para mobilidade dentária na CID-10; usado K08.8 (outros transtornos especificados dos dentes e estruturas de sustentação)
    ('MOBILIDADE_DENTARIA', 'Dente mole (mobilidade dentária)', 'Dente permanente que balança ou ficou frouxo sem trauma recente, geralmente por perda do osso de sustentação.', 'Periodontia', 'ROTINA', 'K08.8', 'dente mole;dente balançando;dente bambo;dente frouxo;dente mexendo;dente solto;dentes abrindo;dente se mexendo sozinho'),
    ('TARTARO', 'Tártaro (cálculo dental)', 'Placa bacteriana endurecida que gruda nos dentes, perto ou abaixo da gengiva, e só sai com limpeza profissional.', 'Periodontia', 'ROTINA', 'K03.6', 'tártaro;tartaro;pedra no dente;placa bacteriana;crosta no dente;sujeira dura no dente;raspagem;cálculo dental;tirar tártaro'),
    -- TERCEIRO_MOLAR: K01.1 dentes impactados (siso semi-incluso/impactado); dente totalmente incluso sem obstrução = K01.0
    ('TERCEIRO_MOLAR', 'Siso (terceiro molar) incluso ou semi-incluso', 'Dente do siso que não nasceu, nasceu só em parte ou está inclinado, com indicação de avaliação para extração.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'ROTINA', 'K01.1', 'siso;dente do siso;tirar o siso;extrair o siso;siso nascendo;siso inclinado;siso deitado;siso encravado;siso incluso;siso semi-incluso;terceiro molar'),
    -- PERICORONARITE: K05.2 inclui pericoronarite aguda; pericoronarite crônica = K05.3
    ('PERICORONARITE', 'Pericoronarite (inflamação na gengiva do siso)', 'Inflamação e infecção da gengiva que cobre um dente nascendo, quase sempre o siso, com dor e dificuldade para abrir a boca.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'URGENCIA', 'K05.2', 'pericoronarite;gengiva do siso inchada;dor no siso;siso inflamado;gengiva em cima do siso;capuz do siso;dor no fundo da boca;siso com pus'),
    ('DENTE_INCLUSO', 'Dente incluso ou impactado (outros que não o siso)', 'Dente que ficou preso no osso ou na gengiva e não nasceu na época certa, como canino incluso.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'ROTINA', 'K01.0', 'dente incluso;dente que não nasceu;dente preso no osso;canino incluso;dente impactado;dente encravado;dente dentro do osso;canino não nasceu'),
    -- EXTRACAO_DENTARIA: K08.3 raiz dentária retida; extração por outros motivos usa o código da doença de base
    ('EXTRACAO_DENTARIA', 'Extração dentária (arrancar dente) ou raiz residual', 'Pedido de extração de dente condenado ou de raiz que ficou na boca, que será avaliado pelo cirurgião-dentista.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'ROTINA', 'K08.3', 'arrancar dente;tirar um dente;extrair dente;dente condenado;arrancar o dente;raiz residual;só sobrou a raiz;resto de raiz;pedaço de raiz'),
    ('ALVEOLITE', 'Alveolite (complicação após extração)', 'Dor forte que começa dois a quatro dias após uma extração, com mau cheiro ou osso exposto no local; precisa de atendimento breve.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'URGENCIA', 'K10.3', 'alveolite;alvéolo seco;buraco da extração doendo;dor dias depois de arrancar;dor depois da extração;cheiro ruim onde tirou o dente;osso exposto onde tirou;coágulo saiu;gosto ruim onde arrancou'),
    -- DOR_INCHACO_POS_OPERATORIO: T81.8 outras complicações de procedimentos; se houver infecção usar T81.4
    ('DOR_INCHACO_POS_OPERATORIO', 'Dor ou inchaço após cirurgia na boca', 'Dor, inchaço, roxo ou pus nos dias seguintes a extração, implante ou outra cirurgia, sem febre alta nem dificuldade para respirar.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'URGENCIA', 'T81.8', 'inchaço após cirurgia;dor após cirurgia;inchou depois da extração;dor forte depois de tirar o dente;pós operatório;pós-operatório;roxo depois da cirurgia;hematoma depois da cirurgia;dor no lugar da cirurgia;gengiva inchada depois da cirurgia'),
    -- CISTO_MAXILARES: K09.2 outros cistos das mandíbulas (cisto da mandíbula SOE); cisto radicular = K04.8; tórus = K10.0
    ('CISTO_MAXILARES', 'Cistos e lesões nos ossos maxilares', 'Cisto ou lesão no osso da mandíbula ou do maxilar, muitas vezes descoberto em radiografia, que precisa de investigação.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'ROTINA', 'K09.2', 'cisto;cisto na mandíbula;cisto no maxilar;cisto no osso;mancha escura no raio-x;lesão no osso da boca;cisto na raiz;cisto no dente;tórus;osso crescendo no céu da boca'),
    ('SIALOLITIASE', 'Pedra na glândula salivar (sialolitíase)', 'Cálculo que entope a glândula salivar e causa inchaço e dor embaixo da língua ou do queixo, principalmente ao comer.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'ROTINA', 'K11.5', 'pedra na glândula;pedra na saliva;cálculo salivar;sialolito;glândula salivar inchada;inchaço embaixo da língua ao comer;caroço duro embaixo da língua;glândula inchada quando como'),
    -- BRUXISMO: na CID-10 o ranger de dentes (teeth-grinding) está incluído em F45.8
    ('BRUXISMO', 'Bruxismo (ranger ou apertar os dentes)', 'Hábito de ranger ou apertar os dentes, de dia ou dormindo, que pode desgastar dentes e causar dor na face.', 'Disfunção Temporomandibular e Dor Orofacial', 'ROTINA', 'F45.8', 'bruxismo;ranger os dentes;range os dentes;apertar os dentes;aperto os dentes;rangendo dormindo;placa de bruxismo;placa para dormir;placa de mordida;acordo com a mandíbula cansada'),
    ('DTM', 'Disfunção temporomandibular (DTM / ATM)', 'Dor ou estalos na articulação da mandíbula, perto do ouvido, com dificuldade ou travamento ao abrir a boca.', 'Disfunção Temporomandibular e Dor Orofacial', 'ROTINA', 'K07.6', 'dtm;atm;dor na mandíbula;estalo na mandíbula;mandíbula estalando;dor no maxilar;boca travada;dor perto do ouvido ao mastigar;queixo travando;mandíbula travada;estalo ao abrir a boca'),
    -- LUXACAO_MANDIBULA: S03.0 luxação do maxilar (dislocation of jaw)
    ('LUXACAO_MANDIBULA', 'Mandíbula deslocada (boca não fecha)', 'Mandíbula que saiu do lugar e a boca não fecha, geralmente após bocejo ou abertura grande; precisa de atendimento no mesmo dia.', 'Cirurgia e Traumatologia Bucomaxilofaciais', 'URGENCIA', 'S03.0', 'boca não fecha;mandíbula deslocada;queixo saiu do lugar;queixo deslocado;maxilar deslocado;boca ficou aberta;mandíbula saiu do lugar;desloquei a mandíbula bocejando'),
    ('AFTAS', 'Aftas', 'Feridas rasas e doloridas na boca, de fundo branco ou amarelado e borda vermelha, que costumam sarar em até 14 dias.', 'Estomatologia', 'ROTINA', 'K12.0', 'afta;aftas;ferida na boca;afta que dói;aftas frequentes;machucado na boca;estomatite aftosa;afta na língua;afta na gengiva'),
    -- HERPES_LABIAL: B00.1 inclui herpes simples labial; gengivoestomatite herpética = B00.2
